let G0 := _root_.CovariantDerivative.chartMetric g0.inner anchor
let B := Poincare.GeodesicTransport.chartChristoffelField bg anchor
let U := (extChartAt (Poincare.closedSmoothModelWithCorners 3) anchor).target ∩
